float rectangleSDF(vec2 p, vec2 b)
{
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0f);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec3 orange = vec3(0.87, 0.5f, 0.0f);
    vec3 red = vec3(1.0f, 0.0f, 0.0f);
    vec2 p = (2.0f * fragCoord - iResolution.xy) / iResolution.y;
    vec3 color;
    float d = rectangleSDF(p , vec2(0.3));

    color = d > 0.0f ? red : orange;

    color *= (1.0f - exp(-50.0f * abs(d)));

    color = 0.7*color+0.3*sin(150.0*d-12.0*iTime)*color;
    fragColor = vec4(color, 1.0f);
}
